import bpy

# Non-destructive bridge write test
name = 'Bridge_Test_Cube'
obj = bpy.data.objects.get(name)
if obj is None:
    bpy.ops.mesh.primitive_cube_add(size=2.0, location=(0.0, 0.0, 1.0))
    obj = bpy.context.active_object
    obj.name = name
    obj['created_by'] = 'OpenAI Blender Bridge'
else:
    bpy.context.view_layer.objects.active = obj

for o in bpy.context.selected_objects:
    o.select_set(False)
obj.select_set(True)
bpy.context.view_layer.objects.active = obj

try:
    for area in bpy.context.screen.areas:
        if area.type == 'VIEW_3D':
            region = next((r for r in area.regions if r.type == 'WINDOW'), None)
            if region is not None:
                with bpy.context.temp_override(window=bpy.context.window, screen=bpy.context.screen, area=area, region=region):
                    bpy.ops.view3d.view_selected(use_all_regions=False)
                break
except Exception:
    pass

print(f'BRIDGE_OK:{obj.name}:{tuple(round(float(v), 3) for v in obj.location)}')
